def fit_ridge(data, degree, lam):
    X = [[(x - 2.0) ** k for k in range(degree + 1)] for x, _ in data]
    n, p = len(X), degree + 1
    M = [[sum(r[i] * r[j] for r in X) + (lam * n if i == j and i > 0 else 0.0) for j in range(p)]
         + [sum(r[i] * y for r, (_, y) in zip(X, data))] for i in range(p)]
    for c in range(p):                      # Gauss-Jordan elimination
        M[c] = [v / M[c][c] for v in M[c]]
        for r in range(p):
            if r != c:
                M[r] = [a - M[r][c] * b for a, b in zip(M[r], M[c])]
    beta = [M[i][p] for i in range(p)]
    return beta, (lambda x: sum(b * (x - 2.0) ** k for k, b in enumerate(beta)))

def mse(predict, data):
    return sum((predict(x) - y) ** 2 for x, y in data) / len(data)

def fit_line(data):
    return fit_ridge(data, 1, 0.0)[1]

train = [(1.0, 2.0), (1.5, 2.8), (2.0, 3.7), (2.5, 4.1), (3.0, 5.2)]
valid = [(0.75, 1.7), (1.75, 3.3), (3.4, 5.6)]
test = [(2.25, 3.9), (2.9, 5.0)]
dev = train + valid
K = 4
folds = [[dev[i] for i in range(len(dev)) if i % K == k] for k in range(K)]

candidates = {
    "line": lambda data: fit_ridge(data, 1, 0.0)[1],
    "curve, lambda 0": lambda data: fit_ridge(data, 4, 0.0)[1],
    "curve, lambda 0.1": lambda data: fit_ridge(data, 4, 0.1)[1],
    "curve, lambda 0.3": lambda data: fit_ridge(data, 4, 0.3)[1],
    "curve, lambda 1": lambda data: fit_ridge(data, 4, 1.0)[1],
}

def cv(fit):
    s = []
    for k in range(K):
        training = [p for j in range(K) if j != k for p in folds[j]]
        s.append(mse(fit(training), folds[k]))
    return sum(s) / K
scores = {name: cv(fit) for name, fit in candidates.items()}
print(min(scores, key=scores.get))
